import sys
from collections import Counter

def input():
    return sys.stdin.readline().strip()

def solution(nums):
    N = len(nums)
    count = Counter(nums)
    ans = 0
    for i in range(N):
        for j in range(N):
            product = nums[i] * nums[j]
            if product in count:
                ans += count[product]

    print(ans)

def main():
    n = int(input())
    solution([int(input()) for _ in range(n)])

if __name__ == "__main__":
    main()
